import{_ as n,A as o,o as i,c as s,j as t,a,C as d,X as c}from"./chunks/framework.BcQZpgl8.js";const g=JSON.parse('{"title":"Python API reference","titleTemplate":":title · PyCellPack","description":"","frontmatter":{},"headers":[],"relativePath":"python/api/index.md","filePath":"python/api/index.md"}'),l={name:"python/api/index.md"};function p(h,e,u,m,y,f){const r=o("DocChoices");return i(),s("div",null,[e[0]||(e[0]=t("h1",{id:"python-api-reference",tabindex:"-1"},[a("Python API reference "),t("a",{class:"header-anchor",href:"#python-api-reference","aria-label":'Permalink to "Python API reference"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("Start with the object that owns your result: a matrix view, a Tensor batch, or a leased NumPy batch. The module pages explain parameters, returns and ownership; their declaration sections come from current Python source and the native type stub. Use the "),t("a",{href:"/CellPack/python/docs/"},"guides"),a(" for complete programs and expected output.")],-1)),d(r,{title:"Find your entry point",items:[{label:"Store",when:"Read or write a matrix",detail:"Lazy selections; decoding returns NumPy or CSR arrays.",href:"/python/api/storage.html"},{label:"ScDataLoader",when:"Feed a training loop",detail:"Corpus sampling and dictionaries of CPU or CUDA Tensors.",href:"/python/api/dataloader.html"},{label:"Loader",when:"Control native batch delivery",detail:"Explicit sources, schemas, planning and leased NumPy output.",href:"/python/api/loader.html"},{label:"scans",when:"Build a custom encoded container",detail:"Chunk and record codecs with explicit metadata and buffers.",href:"/python/api/codecs.html"}]}),e[2]||(e[2]=c('<h2 id="browse-by-responsibility" tabindex="-1">Browse by responsibility <a class="header-anchor" href="#browse-by-responsibility" aria-label="Permalink to &quot;Browse by responsibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Main interfaces</th><th>Reference</th></tr></thead><tbody><tr><td>Matrix storage and file tools</td><td>Store, File, Writer, CSR, read/write/compress, io CPK tools</td><td><a href="/CellPack/python/api/storage.html">Storage</a></td></tr><tr><td>Training Tensor batches</td><td>ScDataset, corpus Accesses, ScDataLoader</td><td><a href="/CellPack/python/api/dataloader.html">Training</a></td></tr><tr><td>Native NumPy loading</td><td>DataSource, OutputSchema, LoaderConfig, Loader</td><td><a href="/CellPack/python/api/loader.html">Loader</a></td></tr><tr><td>Sample sequences</td><td>Native Accesses and AccessFn</td><td><a href="/CellPack/python/api/access-functions.html">Access functions</a></td></tr><tr><td>Output memory and execution</td><td>RingLayout, Ring, Batch, Consumer, Run</td><td><a href="/CellPack/python/api/rings.html">Rings and lifecycle</a></td></tr><tr><td>Cache planning</td><td>PlanOptions, Plan, PageTrace, CostModel</td><td><a href="/CellPack/python/api/planning.html">Planning</a></td></tr><tr><td>Native row processing</td><td>ProcessFn, OutputLayout, model presets, compiler</td><td><a href="/CellPack/python/api/process-functions.html">Process functions</a></td></tr><tr><td>One-host shared loading</td><td>SharedRing, DistributedLoader, DistributedRun</td><td><a href="/CellPack/python/api/distributed.html">Distributed</a></td></tr><tr><td>Diagnostics and calibration</td><td>RunStats, MemoryEstimate, profile reports, costs</td><td><a href="/CellPack/python/api/statistics.html">Statistics</a></td></tr><tr><td>Chunk and record codecs</td><td>scans functions, metadata, tables, reusable encoder/decoder</td><td><a href="/CellPack/python/api/codecs.html">Codecs</a></td></tr><tr><td>Annotated matrices</td><td>read_h5, write_h5cp, write_h5ad, open_matrix, AnnData</td><td><a href="/CellPack/python/api/anndata.html">AnnData</a></td></tr></tbody></table><h2 id="imports-and-dependencies" tabindex="-1">Imports and dependencies <a class="header-anchor" href="#imports-and-dependencies" aria-label="Permalink to &quot;Imports and dependencies&quot;">​</a></h2><p>The distribution and import name are both <code>pycellpack</code>. Common storage, training, planning and loading classes are re-exported at the root. Advanced ring/statistics interfaces live under <code>pycellpack.loader</code>; codecs live under <code>pycellpack.cellpack.scans</code>. The compiled <code>_cellpack</code> module is private.</p><p>Importing the root does not load SciPy, AnnData, h5py, pandas, PyTorch or Numba. Install the optional integration before using it. Torch is installed separately. See <a href="/CellPack/python/docs/installation.html">installation</a>.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><p>Unless noted, counts are integers and byte sizes are bytes. Store selections are orthogonal and retain axes. Output IDs define column order; supply gene identity explicitly rather than relying on names or matching column positions.</p><table tabindex="0"><thead><tr><th>Name</th><th>Import</th><th>Identity space</th></tr></thead><tbody><tr><td>Corpus sample order</td><td><code>from pycellpack import Accesses</code></td><td>Dataset ID and row within the dataset&#39;s Store view</td></tr><tr><td>Native access sequence</td><td><code>from pycellpack.loader import Accesses</code></td><td>Global cell ID assigned by DataSource</td></tr></tbody></table><p>These two <code>Accesses</code> types serve different layers. Use corpus accesses with ScDataLoader and native accesses with Loader.</p><p>Native validation uses ValueError (and Python input type errors use TypeError), I/O uses OSError, and worker/cancellation/busy-state failures use RuntimeError. Async execution errors can arise while iterating or joining. Callback build errors have the process-function exception classes.</p><p>For NumPy batch retention, read <a href="/CellPack/python/api/rings.html">rings and lifecycle</a> before starting a long run. For Tensor transfer and application integration, continue with the <a href="/CellPack/python/training/">training programs</a>.</p>',11))])}const P=n(l,[["render",p]]);export{g as __pageData,P as default};
